"""
SharePoint Entities Custom DataSource
Fetches entity list from SharePoint using Microsoft Graph API
Uses Databricks Python DataSource V2 API with proper secret management
"""


class SharePointEntitiesDataSource(DataSource):
    """
    Custom DataSource for fetching entities from SharePoint list via Graph API
    Uses dbutils.secrets for secure credential access
    """

    @classmethod
    def name(cls):
        return "sharepoint_entities"

    def schema(self):
        """Define the output schema for entity data"""
        return StructType(
            [
                StructField("entity", StringType(), False),
                StructField("entity_name", StringType(), True),
                StructField("list_item_id", StringType(), True),
            ]
        )

    def reader(self, schema: StructType):
        return SharePointEntitiesDataSourceReader(schema, self.options)


class SharePointEntitiesDataSourceReader(DataSourceReader):
    """
    Reader for SharePoint Entities DataSource
    Executes Microsoft Graph API call to fetch entity list
    """

    def __init__(self, schema, options):
        self.schema = schema
        self.options = options

    def read(self, partition):
        """
        Fetch entities from SharePoint list and yield rows
        Handles pagination automatically
        """
        import requests
        from pyspark.sql.types import Row

        # Get configuration from options
        secret_scope = self.options.get("secretScope", "secret-kv101")
        graph_token_key = self.options.get("graphTokenKey")
        site_id = self.options.get("siteId")
        list_id = self.options.get("listId")
        entity_field = self.options.get("entityField", "Entity")

        if not graph_token_key or not site_id or not list_id:
            raise ValueError("Required options: graphTokenKey, siteId, listId")

        # Retrieve token from Databricks secrets using dbutils
        graph_token = dbutils.secrets.get(scope=secret_scope, key=graph_token_key)

        # Build Microsoft Graph API URL
        graph_url = (
            f"https://graph.microsoft.com/v1.0/sites/{site_id}/lists/{list_id}/items"
        )

        headers = {
            "Authorization": f"Bearer {graph_token}",
            "Accept": "application/json",
        }

        params = {"$expand": "fields", "$select": "id,fields", "$top": 5000}

        entities_seen = set()

        while graph_url:
            response = requests.get(
                graph_url, headers=headers, params=params, timeout=60
            )
            response.raise_for_status()

            data = response.json()
            items = data.get("value", [])

            for item in items:
                fields = item.get("fields", {})
                entity_code = fields.get(entity_field)

                if entity_code and entity_code not in entities_seen:
                    entities_seen.add(entity_code)

                    yield Row(
                        entity=entity_code,
                        entity_name=fields.get("Title", entity_code),
                        list_item_id=str(item.get("id", "")),
                    )

            graph_url = data.get("@odata.nextLink")
            params = {}

        print(f"Extracted {len(entities_seen)} unique entities from SharePoint")


