"""
Oracle EPM Custom DataSource with Partitioning
Fetches financial data from Oracle EPM using exportdataslice API
Partitioned by entity x currency x period for parallel execution
Uses Databricks Python DataSource V2 API with proper secret management

Updated: 2026-01-18
- Uses oracle-epm-tokens scope with fresh-access-token (12-hour validity)
- Correct API payload structure (no jobType/jobName)
- BUPALRC/LRCRPT application/plan type
- FY25 as default year (test environment has FY25 data)
"""


@dataclass
class EPMPartition(InputPartition):
    """Partition definition for EPM data extraction"""

    entity: str
    currency: str
    period: str
    year: str


class OracleEPMDataSource(DataSource):
    """
    Custom DataSource for Oracle EPM financial data extraction
    Partitioned by entity x currency x period for parallel processing
    Uses dbutils.secrets for secure credential access
    """

    @classmethod
    def name(cls):
        return "oracle_epm"

    def schema(self):
        """Define the output schema for EPM financial data"""
        return StructType(
            [
                StructField("entity", StringType(), False),
                StructField("cost_centre", StringType(), True),
                StructField("account", StringType(), True),
                StructField("project", StringType(), True),
                StructField("line_of_business", StringType(), True),
                StructField("source", StringType(), True),
                StructField("scenario", StringType(), True),
                StructField("currency", StringType(), False),
                StructField("period", StringType(), False),
                StructField("years", StringType(), False),
                StructField("amount", DecimalType(18, 2), True),
                StructField("source_effective_timestamp", TimestampType(), True),
            ]
        )

    def reader(self, schema: StructType):
        return OracleEPMDataSourceReader(schema, self.options)


class OracleEPMDataSourceReader(DataSourceReader):
    """
    Reader for Oracle EPM DataSource
    Driver: Creates partitions based on entity list and dimension combinations
    Workers: Execute EPM API calls in parallel per partition
    """

    def __init__(self, schema, options):
        self.schema = schema
        self.options = options

    def partitions(self):
        """
        Driver method: Create partitions for entity x currency x period combinations
        Reads entities from upstream DLT table
        """
        import dlt

        entities_table = self.options.get("entitiesTable")
        currencies = self.options.get("currencies", "Local,AUD_Reporting").split(",")
        periods = self.options.get(
            "periods", "Jan,Feb,Mar,Apr,May,Jun,Jul,Aug,Sep,Oct,Nov,Dec"
        ).split(",")
        years = self.options.get("years", "FY25").split(
            ","
        )  # Default to FY25 (test env has FY25 data)

        if not entities_table:
            raise ValueError("entitiesTable option is required")

        # Read entities from upstream DLT table
        entities_df = dlt.read(entities_table)
        entities = [
            row.entity for row in entities_df.select("entity").distinct().collect()
        ]

        # Create partition matrix
        partitions = []
        for entity in entities:
            for currency in currencies:
                for period in periods:
                    for year in years:
                        partitions.append(
                            EPMPartition(
                                entity=entity.strip(),
                                currency=currency.strip(),
                                period=period.strip(),
                                year=year.strip(),
                            )
                        )

        print(
            f"Created {len(partitions)} partitions ({len(entities)} entities x {len(currencies)} currencies x {len(periods)} periods x {len(years)} years)"
        )
        return partitions

    def read(self, partition: EPMPartition) -> Iterator:
        """
        Worker method: Execute EPM API call for this partition
        Runs in parallel across cluster workers
        """
        import requests
        from datetime import datetime
        from pyspark.sql.types import Row
        from decimal import Decimal

        # Get configuration
        secret_scope = self.options.get(
            "secretScope", "oracle-epm-tokens"
        )  # Updated to use new scope
        oracle_token_key = self.options.get(
            "oracleTokenKey", "fresh-access-token"
        )  # Default to fresh token
        base_url = self.options.get("baseUrl")
        application_name = self.options.get(
            "applicationName", "BUPALRC"
        )  # Correct application for test env
        plan_type = self.options.get("planType", "LRCRPT")  # Correct plan type
        object_name = self.options.get("objectName", "ACTUALS")  # ACTUALS or other
        timeout = int(self.options.get("timeout", "300"))

        if not base_url:
            raise ValueError("baseUrl is required option")

        # Retrieve token from Databricks secrets
        try:
            oracle_token = dbutils.secrets.get(scope=secret_scope, key=oracle_token_key)
        except Exception as e:
            raise ValueError(
                f"Failed to retrieve secret from scope 'secret-kv101', key '{oracle_token_key}': {str(e)}"
            )

        # Determine Account dimension based on object_name
        if object_name == "ACTUALS":
            account_filter = "ILvl0Descendants(A_Balance_Sheet)"
            lob_filter = "IDescendants(BS Movements)"
        else:
            account_filter = "ILvl0Descendants(IS_990000_00T)"
            lob_filter = "ILvl0Descendants(Total Line of Business)"

        # Build EPM payload (correct structure - no jobType/jobName)
        payload = {
            "exportPlanningData": False,
            "gridDefinition": {
                "suppressMissingBlocks": True,
                "suppressMissingRows": True,
                "suppressMissingColumns": False,
                "pov": {
                    "dimensions": ["Intercompany", "Version", "View", "Customer"],
                    "members": [
                        ["No Intercompany"],
                        ["Final"],
                        ["Periodic View"],
                        ["No Customer"],
                    ],
                },
                "columns": [{"dimensions": ["Years"], "members": [[partition.year]]}],
                "rows": [
                    {
                        "dimensions": [
                            "Entity",
                            "Cost Centre",
                            "Account",
                            "Project",
                            "Line of Business",
                            "Source",
                            "Scenario",
                            "Currency",
                            "Period",
                        ],
                        "members": [
                            [partition.entity],
                            ["ILvl0Descendants(Total Cost Centre)"],
                            [account_filter],
                            ["ILvl0Descendants(Total Project)"],
                            [lob_filter],
                            ["ILvl0Descendants(LRC_Total)"],
                            ["Actual_ERP"],
                            [partition.currency],
                            [partition.period],
                        ],
                    }
                ],
            },
        }

        url = f"{base_url}/HyperionPlanning/rest/v3/applications/{application_name}/plantypes/{plan_type}/exportdataslice"
        headers = {
            "Authorization": f"Bearer {oracle_token}",
            "Content-Type": "application/json",
        }

        try:
            print(
                f"Calling EPM API for {partition.entity} / {partition.currency} / {partition.period} / {partition.year}"
            )

            response = requests.post(
                url, json=payload, headers=headers, timeout=timeout
            )

            if response.status_code == 401:
                raise Exception(
                    f"EPM API authentication failed (401) - token may be expired. Run refresh_oracle_token.py to generate new token."
                )
            elif response.status_code == 400:
                raise Exception(
                    f"EPM API bad request (400) - check dimension members: {response.text[:500]}"
                )
            elif response.status_code != 200:
                raise Exception(
                    f"EPM API error: {response.status_code} - {response.text[:500]}"
                )

            result = response.json()
            source_timestamp = datetime.now()

            # Parse response structure: {pov: [...], columns: [...], rows: [...]}
            # rows is a list of values (not a dict)
            rows_list = result.get("rows", [])

            if not rows_list or len(rows_list) == 0:
                print(
                    f"WARNING: No data returned for {partition.entity} / {partition.currency} / {partition.period}"
                )
                return iter([])  # Empty iterator

            print(f"Retrieved {len(rows_list)} rows for {partition.entity}")

            # Each row is a simple value (likely the amount)
            # The dimensions are already specified in the request
            # So we just need to extract the amounts
            for row_value in rows_list:
                # Convert row value to Decimal, handle None/#Missing/0
                try:
                    if (
                        row_value is None
                        or row_value == "#Missing"
                        or row_value == ""
                        or row_value == 0
                    ):
                        # Skip rows with no data
                        continue
                    amount = Decimal(str(row_value))
                except (ValueError, TypeError):
                    continue  # Skip invalid values

                # Yield row with fixed dimensions from partition + amount
                # Note: Oracle EPM returns one value per combination we requested
                # The actual dimension breakdowns (Cost Centre, Account, etc.) are aggregated
                yield Row(
                    entity=partition.entity,
                    cost_centre=None,  # Aggregated (not returned in this response structure)
                    account=None,  # Aggregated
                    project=None,  # Aggregated
                    line_of_business=None,  # Aggregated
                    source=None,  # Aggregated
                    scenario="Actual_ERP",
                    currency=partition.currency,
                    period=partition.period,
                    years=partition.year,
                    amount=amount,
                    source_effective_timestamp=source_timestamp,
                )

        except requests.exceptions.Timeout:
            raise Exception(
                f"EPM API request timed out after {timeout} seconds for {partition.entity}"
            )
        except requests.exceptions.RequestException as e:
            raise Exception(f"EPM API request failed for {partition.entity}: {str(e)}")
        except Exception as e:
            raise Exception(
                f"Error processing EPM data for {partition.entity}: {str(e)}"
            )


